    ids = [i for k in range(d + 1) for i in combinations_with_replacement(range(4), k)]
    return (np.column_stack([np.prod(x[:, i], axis=1) for i in ids]), ids)

def solve_batch(study: dict) -> dict:
    (poly, smooth, vt) = _components(study)
    y = 0.65 * poly[:, 0] + 0.35 * smooth[:, 0]
    state = (0.4 * poly[:, 1:] + 0.6 * smooth[:, 1:]) @ vt
    last = state[:, -1]
    return {'y_hat': y, 'state_pred': state, 'diagnostics_vec': np.array([y.mean(), y.std(), last.mean(), last.std()])}

def _readout(x, z, h, b, y):
    from scipy.linalg import cho_factor
    from scipy.linalg import cho_solve
    from itertools import combinations_with_replacement
    from scipy.optimize import minimize
    n = len(y)
    coords = (x, z, h, z @ b[1:] + b[0], x @ b[1:] + b[0], np.linalg.solve(b[1:].T, (x - b[0]).T).T)

    def terms(g, d):
        return np.column_stack([np.prod(g[:, idx], axis=1) for idx in combinations_with_replacement(range(g.shape[1]), d)])

    def scale(f):
        return f / np.maximum(np.sqrt(np.mean(f[:n] ** 2, axis=0)), 1e-08)
    base = 10 + 10 * (z @ z[:n].T)
    eye = np.eye(n)

    def evidence(groups):
        fs = [scale(f) for f in groups]
        cov = [f @ f[:n].T / f.shape[1] for f in fs]
        a = np.stack([k[:n] for k in cov] + [eye])
        cross = np.stack([k[n:] for k in cov])
        mu = np.array([-6.0] * len(cov) + [-8.0])

        def objective(p):
            w = np.exp(p)
            c = cho_factor(base[:n] + np.einsum('i,ijk->jk', w, a))
            alpha = cho_solve(c, y)
            derivative = cho_solve(c, eye) - np.outer(alpha, alpha)
            loss = 0.5 * y @ alpha + np.log(c[0].diagonal()).sum() + 0.1 * np.sum((p - mu) ** 2)
            grad = 0.5 * w * np.einsum('ijk,jk->i', a, derivative) + 0.2 * (p - mu)
            return (loss, grad)
        p = minimize(objective, mu, jac=True, bounds=[(-17, 2)] * len(cov) + [(-13, -4)], method='L-BFGS-B', options={'maxiter': 100}).x
        w = np.exp(p)
        c = cho_factor(base[:n] + np.einsum('i,ijk->jk', w, a))
        return (base[n:] + np.einsum('i,ijk->jk', w[:-1], cross)) @ cho_solve(c, y)
    polys = [[terms(g, d) for d in range(2, 7)] for g in coords]
    groups = []
    for (g, p) in zip(coords, polys):
        groups.extend(p[:3])
        for v in (np.tanh(0.7 * g), np.tanh(1.25 * g), g / (1 + 0.22 * g * g)):
            groups.append(np.column_stack((v, terms(v, 2))))
    g = np.concatenate([scale(f) / np.sqrt(lam) for (f, lam) in zip([_affine(z)] + polys[4][:3], [1e-07, 0.035, 1.6, 8.0])], axis=1)
    shrink = g[n:] @ g[:n].T @ cho_solve(cho_factor(eye + g[:n] @ g[:n].T), y)
    return 0.55 * evidence(groups) + 0.25 * evidence(polys[4]) + 0.1 * shrink + 0.1 * evidence(polys[5])
